<script setup lang="ts">defineProps<{loading?:boolean;error?:Error|null;empty?:boolean}>();defineEmits<{retry:[]}>()</script>
<template><div v-if="loading" class="loading-state" role="status"><span class="spinner"></span>Loading your workspace…</div><div v-else-if="error" class="error-box" role="alert"><strong>We couldn’t load this data.</strong><p>{{error.message}}</p><button class="btn secondary" @click="$emit('retry')">Try again</button></div><div v-else-if="empty" class="empty-state"><slot name="empty">Nothing here yet. You’re all caught up.</slot></div><slot v-else/></template>
